import{_ as r,o as a,c as o,a2 as s}from"./chunks/framework.CqGPl1zp.js";const t="/newx-doc/assets/%E7%95%8C%E9%9D%A2.BuCvQkJm.png",n="/newx-doc/assets/%E8%A1%A8%E7%BB%93%E6%9E%84.DcKQleFL.png",d="/newx-doc/assets/SubscribeHandler.B3xWvP0k.png",i="/newx-doc/assets/UnsubscribeHandler.CMENHYBt.png",f=JSON.parse('{"title":"公众号粉丝","description":"","frontmatter":{},"headers":[],"relativePath":"mp/user.md","filePath":"mp/user.md","lastUpdated":null}'),l={name:"mp/user.md"};function u(c,e,p,m,b,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="公众号粉丝" tabindex="-1">公众号粉丝 <a class="header-anchor" href="#公众号粉丝" aria-label="Permalink to &quot;公众号粉丝&quot;">​</a></h1><p>本章节，讲解公众号粉丝的相关内容，包括关注、取消关注等等，对应 <a href="https://developers.weixin.qq.com/doc/offiaccount/User_Management/Getting_a_User_List.html" target="_blank" rel="noreferrer">《微信公众号官方文档 —— 获取用户列表》</a> 文档。</p><p><img src="'+t+'" alt="粉丝管理"></p><h2 id="_1-表结构" tabindex="-1">1. 表结构 <a class="header-anchor" href="#_1-表结构" aria-label="Permalink to &quot;1. 表结构&quot;">​</a></h2><p>公众号粉丝对应 <code>mp_user</code> 表，结构如下图所示：</p><p><img src="'+n+'" alt="表结构"></p><p>注意，自 2021-12-27 开始，公众号接口不再返回头像和昵称，只能通过微信公众号的网页登录获取。因此，表中的 <code>avatar</code> 和 <code>nickname</code> 字段，往往是空的。</p><h2 id="_2-粉丝管理界面" tabindex="-1">2. 粉丝管理界面 <a class="header-anchor" href="#_2-粉丝管理界面" aria-label="Permalink to &quot;2. 粉丝管理界面&quot;">​</a></h2><ul><li>前端：<a href="https://github.com/yudaocode/yudao-ui-admin-vue2/blob/master/src/views/mp/user/index.vue" target="_blank" rel="noreferrer">/@views/mp/user</a></li><li>后端：<a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/controller/admin/user/MpUserController.java" target="_blank" rel="noreferrer">MpUserController</a></li></ul><h2 id="_3-同步粉丝" tabindex="-1">3. 同步粉丝 <a class="header-anchor" href="#_3-同步粉丝" aria-label="Permalink to &quot;3. 同步粉丝&quot;">​</a></h2><p>点击粉丝管理界面的【同步】按钮，可以 <strong>异步</strong> 从公众号同步所有的粉丝信息，存储到 <code>mp_user</code> 表中。如果你的粉丝较多，可能需要等待一段时间。</p><p>对应后端的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/service/user/MpUserServiceImpl.java#L95-L161" target="_blank" rel="noreferrer">MpUserServiceImpl</a> 的 <code>syncUser</code> 方法。</p><h2 id="_4-关注-subscribehandler" tabindex="-1">4. 关注 SubscribeHandler <a class="header-anchor" href="#_4-关注-subscribehandler" aria-label="Permalink to &quot;4. 关注 SubscribeHandler&quot;">​</a></h2><p>用户关注公众号时，会触发 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/service/handler/user/SubscribeHandler.java" target="_blank" rel="noreferrer">SubscribeHandler</a> 处理器，新增或修改 <code>mp_user</code> 粉丝信息。</p><p>图片纠错：最新版本不区分 yudao-module-mp-api 和 yudao-module-mp-biz 子模块，代码直接合并到 yudao-module-mp 模块的 src 目录下，更适合单体项目</p><p><img src="'+d+'" alt="SubscribeHandler"></p><h2 id="_5-取关-unsubscribehandler" tabindex="-1">5. 取关 UnsubscribeHandler <a class="header-anchor" href="#_5-取关-unsubscribehandler" aria-label="Permalink to &quot;5. 取关 UnsubscribeHandler&quot;">​</a></h2><p>用户取消关注公众号时，会触发 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-module-mp/src/main/java/cn/iocoder/yudao/module/mp/service/handler/user/UnsubscribeHandler.java" target="_blank" rel="noreferrer">UnsubscribeHandler</a> 处理器，标记 <code>mp_user</code> 粉丝信息为取消关注，设置 <code>subscribe_status</code> 字段为 0。</p><p>图片纠错：最新版本不区分 yudao-module-mp-api 和 yudao-module-mp-biz 子模块，代码直接合并到 yudao-module-mp 模块的 src 目录下，更适合单体项目</p><p><img src="'+i+'" alt="UnsubscribeHandler"></p>',20)])])}const v=r(l,[["render",u]]);export{f as __pageData,v as default};
